# MODIFICADO: Arturo Diaz Lora - 2026-04-04 06:30
# Razón: COTSS debe incluir OREM (incentivos, horas extra) según Ley 87-01 Art. 47
# TSS se calcula sobre TODA la remuneración: salario + comisiones + bonos + horas extra

# COTSS = SALARIO (salario + comisiones) + OREM (incentivos + horas extra)
tss_playslip = categories.get('SALARIO', 0.0) + categories.get('OREM', 0.0)
tss_allowance_accumulation = payslip.sum_category('SALARIO', start_date) + payslip.sum_category('OREM', start_date)

if end_month:
    result = tss_playslip + tss_allowance_accumulation

elif both_month:
    result = tss_playslip

elif start_month:
    if bool(inputs.get('DLAB') and inputs.get('DLAB').amount):
        if wage_type == 'hourly':
            result = contract.hourly_wage * inputs.get('DLAB').amount
        else:
            result = (contract.wage / contract.payment_day) * inputs.get('DLAB').amount
    else:
        result = tss_playslip

tss_playslip = categories.get('SALARIO', 0.0)
tss_allowance_accumulation = payslip.sum_category('SALARIO', start_date)

if end_month:
    tss_playslip = tss_allowance_accumulation 
    result = tss_playslip 

if both_month:
    result = tss_playslip + tss_allowance_accumulation

elif start_month:
