    result = tss_playslip

# 2026-03-18 — Arturo Diaz Lora — Fix: tope quincenal = tope mensual / 2 para both_month
afp_maximum = payslip.env["hr.payslip"].get_quotation_calculation("SVDS").value
afp_percentage = payslip.env["hr.payslip"].get_quotation_calculation("SVDS").retention / 100
afp_withholding_accumulation = 0
effective_afp_max = afp_maximum / 2 if both_month else afp_maximum

if COTSS <= effective_afp_max:
    svdse_amount = (COTSS * afp_percentage - afp_withholding_accumulation) * -1
else:
    svdse_amount = (effective_afp_max * afp_percentage - afp_withholding_accumulation) * -1

if both_month:
    result = svdse_amount * multiple
else:
    result = svdse_amount

result = 0
if employee.family_ids:
    dependant_withholding = 0
